inline uint64_t hex64(const std::string& s) {
    if (s.empty()) throw std::runtime_error("hex field");
    uint64_t v = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        uint64_t d;
        if (c >= '0' && c <= '9') d = static_cast<uint64_t>(c - '0');
        else if (c >= 'a' && c <= 'f') d = static_cast<uint64_t>(c - 'a' + 10);
        else throw std::runtime_error("hex digit");
        v = (v << 4) | d;
    }
    return v;
}

