inline void image_write_json(const ImageData& d) {
    static const char* HEX = "0123456789abcdef";
    std::string out;
    out.reserve(1024);
    char buf[80];

    auto key_hex = [&buf, HEX](uint64_t v, int digits) {
        for (int i = digits - 1; i >= 0; --i) {
            buf[i] = HEX[v & 0xF];
            v >>= 4;
        }
        buf[digits] = 0;
        return buf;
    };
    auto loc = [&out](const ImageLoc& x) {
        out += '[';
        out += std::to_string(x.stage);
        out += ',';
        out += std::to_string(x.cell);
        out += ']';
    };
    auto fronts = [&out, &key_hex](const std::vector<ImageFront>& v, int width) {
        out += '[';
        for (size_t i = 0; i < v.size(); ++i) {
            if (i) out += ',';
            out += "[\"";
            out += key_hex(v[i].key, width);
            out += "\",";
            out += std::to_string(v[i].loc.stage);
            out += ',';
            out += std::to_string(v[i].loc.cell);
            out += ']';
        }
        out += ']';
    };

    out += "{\"root\":";
    if (d.root.stage < 0) out += "null";
    else loc(d.root);
    out += ",\"front16\":";
    fronts(d.front16, 4);
    out += ",\"front64\":";
    fronts(d.front64, 16);
    out += ",\"cells\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) out += ',';
        out += std::to_string(d.cells[s]);
    }
    out += "],\"banks\":[";
    for (int s = 0; s < RAM_NUM; ++s) {
        if (s) out += ',';
        out += '[';
        for (size_t i = 0; i < d.banks[s].size(); ++i) {
            if (i) out += ',';
            out += '"';
            out += image_word_hex(d.banks[s][i]);
            out += '"';
        }
        out += ']';
    }
    out += "],\"bitmaps\":[";
    for (size_t i = 0; i < d.bitmaps.size(); ++i) {
        if (i) out += ',';
        out += '"';
        out += key_hex(d.bitmaps[i], 16);
        out += '"';
    }
    out += "],\"nexthops\":[";
    for (size_t i = 0; i < d.nexthops.size(); ++i) {
        if (i) out += ',';
        out += std::to_string(d.nexthops[i]);
    }
    out += "]}";
    std::cout << out;
}

